import React, { useState, useEffect } from 'react';
import { 
  getPartidos, addPartido, updatePartido, deletePartido,
  getAsistenciaPartidos, updateAsistenciaPartido, getJugadores,
  generarPagosPartido
} from '../../database/db';
import './GestionPartidos.css';

function GestionPartidos() {
  const [partidos, setPartidos] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [editando, setEditando] = useState(null);
  const [verConvocatoria, setVerConvocatoria] = useState(null);
  const [jugadores, setJugadores] = useState([]);
  const [convocatoriaData, setConvocatoriaData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    fecha: '',
    hora: '',
    rival: '',
    lugar: '',
    monto_pago: 0
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    setLoading(true);
    try {
      const [partidosData, jugadoresData] = await Promise.all([
        getPartidos(),
        getJugadores()
      ]);
      setPartidos(partidosData);
      setJugadores(jugadoresData);
    } catch (error) {
      console.error('Error cargando datos:', error);
      alert('Error al cargar los datos');
    }
    setLoading(false);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);
    try {
      if (editando) {
        await updatePartido(editando.Id, formData);
        alert('✅ Partido actualizado');
      } else {
        const nuevo = await addPartido(formData);
        if (formData.monto_pago > 0) {
          await generarPagosPartido(nuevo.id);
        }
        alert('✅ Partido programado');
      }
      setShowForm(false);
      setEditando(null);
      setFormData({ fecha: '', hora: '', rival: '', lugar: '', monto_pago: 0 });
      await cargarDatos();
    } catch (error) {
      alert('Error: ' + error.message);
    }
    setLoading(false);
  };

  const handleDelete = async (id) => {
    if (window.confirm('¿Eliminar este partido?')) {
      try {
        await deletePartido(id);
        await cargarDatos();
        alert('❌ Partido eliminado');
      } catch (error) {
        alert('Error al eliminar: ' + error.message);
      }
    }
  };

  const verListaConvocatoria = async (partido) => {
    setLoading(true);
    try {
      const convocatoria = await getAsistenciaPartidos();
      const filtrada = convocatoria.filter(c => c.PartidoId === partido.Id);
      setConvocatoriaData(filtrada);
      setVerConvocatoria(partido);
    } catch (error) {
      alert('Error al cargar convocatoria: ' + error.message);
    }
    setLoading(false);
  };

  const cambiarEstadoConvocatoria = async (partidoId, jugadorId, nuevoEstado) => {
    try {
      await updateAsistenciaPartido(partidoId, jugadorId, nuevoEstado);
      const convocatoria = await getAsistenciaPartidos();
      setConvocatoriaData(convocatoria.filter(c => c.PartidoId === partidoId));
    } catch (error) {
      alert('Error al cambiar estado: ' + error.message);
    }
  };

  const generarPagos = async (partidoId, monto) => {
    if (monto > 0) {
      try {
        await generarPagosPartido(partidoId);
        alert('💰 Pagos generados para todos los jugadores');
        await cargarDatos();
      } catch (error) {
        alert('Error al generar pagos: ' + error.message);
      }
    } else {
      alert('⚠️ El monto es 0, no se generaron pagos');
    }
  };

  const getEstadoBadge = (estado) => {
    const badges = {
      'convocado': { class: 'badge-convocado', text: '📋 Convocado', color: '#2196F3' },
      'jugo': { class: 'badge-jugo', text: '⚽ Jugó', color: '#4CAF50' },
      'falta': { class: 'badge-falta', text: '❌ Falta', color: '#f44336' },
      'no_convocado': { class: 'badge-no', text: '⭕ No convocado', color: '#9e9e9e' }
    };
    return badges[estado] || badges.convocado;
  };

  const getJugadorById = (id) => jugadores.find(j => j.Id === id);

  if (loading && partidos.length === 0) {
    return <div className="loading-container">Cargando partidos...</div>;
  }

  return (
    <div className="gestion-partidos">
      <div className="header-actions">
        <h2><i className="fas fa-trophy"></i> Gestionar Partidos</h2>
        <button className="btn-agregar" onClick={() => { setShowForm(true); setEditando(null); }}>
          <i className="fas fa-plus"></i> <span>Programar</span>
        </button>
      </div>

      <div className="partidos-list">
        {partidos.length === 0 ? (
          <div className="empty-state">
            <i className="fas fa-trophy"></i>
            <p>No hay partidos programados</p>
            <button className="btn-primary" onClick={() => setShowForm(true)}>Programar primer partido</button>
          </div>
        ) : (
          partidos.map(part => (
            <div key={part.Id} className="partido-card">
              <div className="partido-header">
                <div className="rival-info">
                  <i className="fas fa-trophy"></i>
                  <div>
                    <h3>vs {part.Rival}</h3>
                    <p><i className="fas fa-calendar"></i> {new Date(part.Fecha).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' })}</p>
                    <p><i className="fas fa-clock"></i> {part.Hora} hrs · {part.Lugar}</p>
                  </div>
                </div>
                <div className="monto-info">
                  <span className="monto">💰 ${part.MontoPago}</span>
                  <button className="btn-generar-pagos" onClick={() => generarPagos(part.Id, part.MontoPago)}>
                    <i className="fas fa-dollar-sign"></i> Pagos
                  </button>
                </div>
              </div>
              
              {part.Resultado && (
                <div className="partido-resultado">
                  <i className="fas fa-chart-line"></i>
                  <strong>Resultado:</strong> {part.Resultado}
                </div>
              )}
              
              <div className="partido-footer">
                <button className="btn-convocatoria" onClick={() => verListaConvocatoria(part)}>
                  <i className="fas fa-clipboard-list"></i> <span>Ver Convocatoria</span>
                </button>
                <button className="btn-editar" onClick={() => { 
                  setEditando(part); 
                  setFormData({
                    fecha: part.Fecha,
                    hora: part.Hora,
                    rival: part.Rival,
                    lugar: part.Lugar,
                    monto_pago: part.MontoPago
                  }); 
                  setShowForm(true); 
                }}>
                  <i className="fas fa-edit"></i>
                </button>
                <button className="btn-eliminar" onClick={() => handleDelete(part.Id)}>
                  <i className="fas fa-trash"></i>
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      {/* Modal Formulario */}
      {showForm && (
        <div className="modal-overlay" onClick={() => setShowForm(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>{editando ? '✏️ Editar Partido' : '🏆 Programar Partido'}</h3>
              <button className="close-btn" onClick={() => setShowForm(false)}>&times;</button>
            </div>
            <form onSubmit={handleSubmit}>
              <div className="form-row">
                <div className="form-group">
                  <label><i className="fas fa-calendar"></i> Fecha *</label>
                  <input type="date" value={formData.fecha} onChange={(e) => setFormData({...formData, fecha: e.target.value})} required />
                </div>
                <div className="form-group">
                  <label><i className="fas fa-clock"></i> Hora *</label>
                  <input type="time" value={formData.hora} onChange={(e) => setFormData({...formData, hora: e.target.value})} required />
                </div>
              </div>
              
              <div className="form-group">
                <label><i className="fas fa-flag-checkered"></i> Rival *</label>
                <input type="text" value={formData.rival} onChange={(e) => setFormData({...formData, rival: e.target.value})} placeholder="Ej: Los Tigres" required />
              </div>
              
              <div className="form-group">
                <label><i className="fas fa-map-marker-alt"></i> Lugar *</label>
                <input type="text" value={formData.lugar} onChange={(e) => setFormData({...formData, lugar: e.target.value})} placeholder="Ej: Estadio Principal" required />
              </div>
              
              <div className="form-group">
                <label><i className="fas fa-dollar-sign"></i> Monto a pagar ($)</label>
                <input type="number" value={formData.monto_pago} onChange={(e) => setFormData({...formData, monto_pago: parseInt(e.target.value) || 0})} placeholder="0 = gratis" />
              </div>
              
              <div className="form-buttons">
                <button type="button" className="btn-cancelar" onClick={() => setShowForm(false)}>Cancelar</button>
                <button type="submit" className="btn-guardar" disabled={loading}>
                  {loading ? <i className="fas fa-spinner fa-spin"></i> : (editando ? 'Actualizar' : 'Programar')}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Modal Convocatoria */}
      {verConvocatoria && (
        <div className="modal-overlay" onClick={() => setVerConvocatoria(null)}>
          <div className="modal-content large" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3><i className="fas fa-clipboard-list"></i> Convocatoria - vs {verConvocatoria.Rival}</h3>
              <button className="close-btn" onClick={() => setVerConvocatoria(null)}>&times;</button>
            </div>
            
            <div className="convocatoria-resumen">
              <div className="resumen-item">
                <span>📋 Convocados:</span>
                <strong>{convocatoriaData.filter(c => c.Estado === 'convocado').length}</strong>
              </div>
              <div className="resumen-item">
                <span>⚽ Jugaron:</span>
                <strong>{convocatoriaData.filter(c => c.Estado === 'jugo').length}</strong>
              </div>
              <div className="resumen-item">
                <span>❌ No jugaron:</span>
                <strong>{convocatoriaData.filter(c => c.Estado === 'falta').length}</strong>
              </div>
            </div>

            <div className="convocatoria-list">
              {convocatoriaData.map(c => {
                const jugador = getJugadorById(c.JugadorId);
                const badge = getEstadoBadge(c.Estado);
                if (!jugador) return null;
                
                return (
                  <div key={c.Id} className="convocatoria-item">
                    <div className="jugador-info">
                      <span className="numero">#{jugador.NumeroCamiseta}</span>
                      <span className="nombre">{jugador.Nombre}</span>
                      <span className="posicion">{jugador.Posicion}</span>
                    </div>
                    <div className="estado-actual">
                      <span className={badge.class}>{badge.text}</span>
                    </div>
                    <div className="acciones-convocatoria">
                      <button className="btn-jugo-small" onClick={() => cambiarEstadoConvocatoria(verConvocatoria.Id, c.JugadorId, 'jugo')}>⚽</button>
                      <button className="btn-falta-small" onClick={() => cambiarEstadoConvocatoria(verConvocatoria.Id, c.JugadorId, 'falta')}>❌</button>
                      <button className="btn-convocado-small" onClick={() => cambiarEstadoConvocatoria(verConvocatoria.Id, c.JugadorId, 'convocado')}>📋</button>
                    </div>
                  </div>
                );
              })}
            </div>
            
            <div className="modal-footer">
              <button className="btn-cerrar" onClick={() => setVerConvocatoria(null)}>Cerrar</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

export default GestionPartidos;
